import { writeFileSync, mkdtempSync, rmSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';

// --- API contract checks ---

// Cycle of 3: a->b->c->a
assert.throws(() => planJobs([
  {id:'a',deps:['b'],state:'pending'},
  {id:'b',deps:['c'],state:'pending'},
  {id:'c',deps:['a'],state:'pending'}
]), Error, '3-cycle should throw');

// Self-dependency
assert.throws(() => planJobs([{id:'a',deps:['a'],state:'pending'}]), Error, 'self-dep should throw');

// Cycle through failed/succeeded nodes
