// Malformed: non-string id
assert.throws(() => planJobs([{id:42,deps:[],state:'pending'}]), Error, 'non-string id should throw');

// Malformed: empty id
assert.throws(() => planJobs([{id:'',deps:[],state:'pending'}]), Error, 'empty id should throw');

// Malformed: bad state
assert.throws(() => planJobs([{id:'a',deps:[],state:'running'}]), Error, 'bad state should throw');

// Malformed: deps not array
assert.throws(() => planJobs([{id:'a',deps:'x',state:'pending'}]), Error, 'deps not array should throw');

// Malformed: spec not array
assert.throws(() => planJobs('nope'), Error, 'spec not array should throw');

// __proto__ and constructor as ordinary IDs
assert.deepEqual(
  planJobs([{id:'__proto__',deps:[],state:'pending'},{id:'constructor',deps:['__proto__'],state:'pending'}]),
  {order:['__proto__','constructor'],ready:['__proto__'],blocked:[]},
  '__proto__/constructor'
);

// Unknown fields ignored
assert.deepEqual(
  planJobs([{id:'a',deps:[],state:'pending',extra:123,foo:'bar'}]),
  {order:['a'],ready:['a'],blocked:[]},
  'unknown fields ignored'
);

// Transitive blocked through succeeded intermediate
assert.deepEqual(
  planJobs([
    {id:'f',deps:[],state:'failed'},
    {id:'s',deps:['f'],state:'succeeded'},
    {id:'p',deps:['s'],state:'pending'}
  ]),
  {order:[],ready:[],blocked:[{id:'p',causes:['f']}]},
