);

// Transitive blocked through failed intermediate
assert.deepEqual(
  planJobs([
    {id:'f1',deps:[],state:'failed'},
    {id:'f2',deps:['f1'],state:'failed'},
    {id:'p',deps:['f2'],state:'pending'}
  ]),
