  'pending dep not ready'
);

// No mutation of input
const orig = [{id:'a',deps:[],state:'pending'}];
const origCopy = JSON.parse(JSON.stringify(orig));
planJobs(orig);
assert.deepEqual(orig, origCopy, 'input not mutated');

// Empty input
assert.deepEqual(planJobs([]), {order:[],ready:[],blocked:[]}, 'empty input');

// Deterministic Kahn ordering: smallest zero-indegree first
