  } catch (e) {
    threw = true;
    assert.equal(e.status, 2, 'CLI two-args exit 2');
  }
  assert.ok(threw, 'CLI two-args should fail');

  // Unreadable file -> exit 2
  threw = false;
  try {
    execFileSync('node', ['job-plan.js', join(dir, 'nonexistent.json')], { encoding: 'utf8', stdio: ['pipe','pipe','pipe'] });
  } catch (e) {
    threw = true;
    assert.equal(e.status, 2, 'CLI unreadable exit 2');
    assert.ok(e.stderr.length > 0, 'CLI unreadable stderr nonempty');
    assert.equal(e.stdout, '', 'CLI unreadable no stdout');
  }
  assert.ok(threw, 'CLI unreadable should fail');

  // Invalid JSON -> exit 2
  const badJson = join(dir, 'bad.json');
  writeFileSync(badJson, 'not json');
  threw = false;
  try {
    execFileSync('node', ['job-plan.js', badJson], { encoding: 'utf8', stdio: ['pipe','pipe','pipe'] });
  } catch (e) {
    threw = true;
    assert.equal(e.status, 2, 'CLI bad JSON exit 2');
    assert.ok(e.stderr.length > 0, 'CLI bad JSON stderr nonempty');
    assert.equal(e.stdout, '', 'CLI bad JSON no stdout');
  }
  assert.ok(threw, 'CLI bad JSON should fail');

  // Invalid graph (cycle) -> exit 2
  const badGraph = join(dir, 'cycle.json');
  writeFileSync(badGraph, JSON.stringify([
    {id:'a',deps:['b'],state:'pending'},
    {id:'b',deps:['a'],state:'pending'}
  ]));
  threw = false;
  try {
    execFileSync('node', ['job-plan.js', badGraph], { encoding: 'utf8', stdio: ['pipe','pipe','pipe'] });
  } catch (e) {
    threw = true;
    assert.equal(e.status, 2, 'CLI cycle exit 2');
    assert.ok(e.stderr.length > 0, 'CLI cycle stderr nonempty');
    assert.equal(e.stdout, '', 'CLI cycle no stdout');
  }
  assert.ok(threw, 'CLI cycle should fail');

  // Importing module must not run CLI (no stdout/stderr side effects)
  // Already proven by the fact that this script imported planJobs without CLI output.
} finally {
  rmSync(dir, { recursive: true, force: true });
}

