// Deterministic job dependency planner.

const STATES = new Set(['pending', 'succeeded', 'failed']);

function isNonemptyString(v) {
  return typeof v === 'string' && v.length > 0;
}

function throwErr(msg) {
  throw new Error(msg);
}

// Code-unit string ordering (JS < / >), not locale collation.
function less(a, b) {
  return a < b;
}

function sortAsc(arr) {
  arr.sort((a, b) => (a < b ? -1 : a > b ? 1 : 0));
  return arr;
}

export function planJobs(spec) {
  // Validate top-level shape.
  if (!Array.isArray(spec)) {
    throwErr('spec must be an array');
  }

  // Validate each job and build maps. We do NOT mutate the input.
  const jobs = new Map(); // id -> { id, deps, state }
  for (let i = 0; i < spec.length; i++) {
    const job = spec[i];
    if (job === null || typeof job !== 'object' || Array.isArray(job)) {
      throwErr(`job at index ${i} must be an object`);
    }
    if (!isNonemptyString(job.id)) {
      throwErr(`job at index ${i} has malformed id`);
    }
    if (jobs.has(job.id)) {
      throwErr(`duplicate id: ${job.id}`);
    }
    if (!Array.isArray(job.deps)) {
      throwErr(`job ${job.id} has malformed deps`);
    }
    const seenDeps = new Set();
    for (let d = 0; d < job.deps.length; d++) {
      const dep = job.deps[d];
      if (!isNonemptyString(dep)) {
        throwErr(`job ${job.id} has malformed dep`);
      }
      if (seenDeps.has(dep)) {
        throwErr(`job ${job.id} has duplicate dependency ${dep}`);
      }
      seenDeps.add(dep);
    }
    if (typeof job.state !== 'string' || !STATES.has(job.state)) {
      throwErr(`job ${job.id} has malformed state`);
    }
    jobs.set(job.id, { id: job.id, deps: job.deps, state: job.state });
  }

  // Every referenced ID must exist.
  for (const [id, j] of jobs) {
    for (const dep of j.deps) {
      if (!jobs.has(dep)) {
        throwErr(`job ${id} references unknown id ${dep}`);
      }
    }
  }

  // Build adjacency: dep -> [dependents]. Compute indegrees.
  const children = new Map(); // dep -> array of dependent ids
  const indegree = new Map(); // id -> number of deps
  for (const [id, j] of jobs) {
    indegree.set(id, j.deps.length);
    for (const dep of j.deps) {
      if (!children.has(dep)) children.set(dep, []);
      children.get(dep).push(id);
    }
  }

  // Kahn's algorithm with deterministic tie-breaking: always pick the
  // lexically smallest (code-unit <) currently zero-indegree id.
  const heap = [];
  function heapPush(x) {
    heap.push(x);
    let i = heap.length - 1;
    while (i > 0) {
      const p = (i - 1) >> 1;
      if (less(heap[i], heap[p])) {
        const t = heap[i]; heap[i] = heap[p]; heap[p] = t;
        i = p;
      } else break;
    }
  }
  function heapPop() {
    const top = heap[0];
    const last = heap.pop();
    if (heap.length > 0) {
      heap[0] = last;
      let i = 0;
      const n = heap.length;
      while (true) {
        let s = i;
        const l = 2 * i + 1;
        const r = 2 * i + 2;
        if (l < n && less(heap[l], heap[s])) s = l;
        if (r < n && less(heap[r], heap[s])) s = r;
        if (s !== i) {
          const t = heap[i]; heap[i] = heap[s]; heap[s] = t;
          i = s;
        } else break;
      }
    }
    return top;
  }

  for (const [id, deg] of indegree) {
    if (deg === 0) heapPush(id);
  }

  const topoOrder = [];
  while (heap.length > 0) {
    const id = heapPop();
    topoOrder.push(id);
    const kids = children.get(id);
    if (kids) {
      for (const kid of kids) {
        const nd = indegree.get(kid) - 1;
        indegree.set(kid, nd);
        if (nd === 0) heapPush(kid);
      }
    }
  }

  if (topoOrder.length !== jobs.size) {
    throwErr('dependency cycle detected');
  }

  // Compute failed ancestors for each job (transitive closure of failed deps).
  // Process in topological order so that when we process a node, all its
  // deps have already been processed.
  const failedAncestors = new Map(); // id -> Set of failed ancestor ids
  for (const id of topoOrder) {
    const j = jobs.get(id);
    const set = new Set();
    for (const dep of j.deps) {
      const depSet = failedAncestors.get(dep);
      if (depSet) {
        for (const f of depSet) set.add(f);
      }
      if (jobs.get(dep).state === 'failed') {
        set.add(dep);
      }
    }
    failedAncestors.set(id, set);
  }

  // Build results.
  const order = [];
  const ready = [];
  const blocked = [];

  for (const id of topoOrder) {
    const j = jobs.get(id);
    if (j.state !== 'pending') continue;

    const failedSet = failedAncestors.get(id);
    const isBlocked = failedSet && failedSet.size > 0;

    if (isBlocked) {
      const causes = sortAsc([...failedSet]);
      blocked.push({ id, causes });
    } else {
      order.push(id);
      // ready: all direct deps are succeeded
      let allSucceeded = true;
      for (const dep of j.deps) {
        if (jobs.get(dep).state !== 'succeeded') {
          allSucceeded = false;
          break;
        }
      }
      if (allSucceeded) {
        ready.push(id);
      }
    }
  }

  // blocked is sorted by id.
  blocked.sort((a, b) => (a.id < b.id ? -1 : a.id > b.id ? 1 : 0));
  // ready: sorted by id.
  sortAsc(ready);

  return { order, ready, blocked };
}

// --- CLI ---
import { readFileSync, realpathSync } from 'node:fs';
import process from 'node:process';

const isMain = (() => {
  try {
    const entry = process.argv[1];
    if (!entry) return false;
    return realpathSync(entry) === realpathSync(new URL(import.meta.url).pathname);
  } catch {
    return false;
  }
})();

if (isMain) {
  const args = process.argv.slice(2);
  if (args.length !== 1) {
    process.stderr.write('usage: node job-plan.js SPECFILE\n');
    process.exit(2);
  }
  let raw;
  try {
    raw = readFileSync(args[0], 'utf8');
  } catch (e) {
    process.stderr.write(`cannot read ${args[0]}: ${e.message}\n`);
    process.exit(2);
  }
  let spec;
  try {
    spec = JSON.parse(raw);
  } catch (e) {
    process.stderr.write(`invalid JSON: ${e.message}\n`);
    process.exit(2);
  }
  try {
    const plan = planJobs(spec);
    process.stdout.write(JSON.stringify(plan) + '\n');
    process.exit(0);
  } catch (e) {
    process.stderr.write(`invalid graph: ${e.message}\n`);
    process.exit(2);
  }
}

